import 'dart:convert';
import 'dart:io';

/// UI milestone: the data artifact contains all groups, but the Crews tab
/// starts with the top N by release count.
const int kCrewInitialLimit = 128;

/// One release ZIP attributed to a crew (generated by
/// `tools/crew-analysis` into `crews.json`).
class CrewRelease {
  const CrewRelease({
    required this.rel,
    required this.letter,
    required this.folder,
    required this.zip,
    required this.title,
    required this.year,
    required this.publisher,
    required this.crackedBy,
    required this.crew,
    required this.language,
    required this.source,
    required this.disks,
    required this.rawDump,
    required this.pastiDump,
    required this.boxscan,
    required this.ambiguous,
    required this.tosBad,
    required this.specialFlag,
    required this.specialNote,
    this.size,
  });

  factory CrewRelease.fromJson(Map<String, dynamic> json) {
    String str(String key) => (json[key] ?? '').toString().trim();
    int integer(String key) => (json[key] as num?)?.toInt() ?? 0;
    bool flag(String key) => json[key] == true;
    return CrewRelease(
      rel: str('rel'),
      letter: str('letter'),
      folder: str('folder'),
      zip: str('zip'),
      title: str('title'),
      year: str('year'),
      publisher: str('publisher'),
      crackedBy: str('cracked_by'),
      crew: str('crew'),
      language: str('language'),
      source: str('source'),
      disks: integer('disks'),
      rawDump: flag('raw_dump'),
      pastiDump: flag('pasti_dump'),
      boxscan: flag('boxscan'),
      ambiguous: flag('ambiguous'),
      tosBad: str('tos_bad'),
      specialFlag: str('special_flag'),
      specialNote: str('special_note'),
      size: (json['size'] as num?)?.toInt(),
    );
  }

  final String rel;
  final String letter;
  final String folder;
  final String zip;
  final String title;
  final String year;
  final String publisher;
  final String crackedBy;
  final String crew;
  final String language;
  final String source;
  final int disks;
  final bool rawDump;
  final bool pastiDump;
  final bool boxscan;
  final bool ambiguous;
  final String tosBad;
  final String specialFlag;
  final String specialNote;
  final int? size;
}

/// One crew/scene group from `crews.json`.
class CrewGroup {
  const CrewGroup({
    required this.id,
    required this.name,
    required this.kind,
    required this.rank,
    required this.zips,
    required this.aliases,
    required this.releases,
    this.image,
    this.excluded = false,
  });

  factory CrewGroup.fromJson(Map<String, dynamic> json) {
    return CrewGroup(
      id: (json['id'] ?? '').toString(),
      name: (json['name'] ?? '').toString(),
      kind: (json['kind'] ?? 'crew').toString(),
      rank: (json['rank'] as num?)?.toInt() ?? 0,
      zips: (json['zips'] as num?)?.toInt() ?? 0,
      excluded: json['excluded'] == true,
      aliases: ((json['aliases'] as List<dynamic>?) ?? const [])
          .map((e) => e.toString())
          .where((e) => e.trim().isNotEmpty)
          .toList(),
      image: (json['image'] as String?)?.trim().isEmpty ?? true
          ? null
          : (json['image'] as String).trim(),
      releases: ((json['releases'] as List<dynamic>?) ?? const [])
          .whereType<Map<String, dynamic>>()
          .map(CrewRelease.fromJson)
          .where((r) => r.rel.isNotEmpty)
          .toList(),
    );
  }

  final String id;
  final String name;

  /// `crew` or `cracker` (the analysis prefers `crew` over `cracked_by`).
  final String kind;
  final int rank;
  final int zips;
  final List<String> aliases;

  /// Hidden from the Crews tab (general exclusion list in the crew-analysis
  /// tool); the group still exists in `crews.json` for audit/ranking.
  final bool excluded;

  /// Optional curated image (cracktro/logo) from a later analysis phase.
  final String? image;
  final List<CrewRelease> releases;
}

/// Curated crew card image (`crew-images.json`, generated/edited by the
/// crew-analysis tool or manually). `rel` is the release ZIP index path and
/// `name` the image basename below its screenshot directory.
class CrewImage {
  const CrewImage({
    required this.rel,
    required this.name,
    this.source = '',
    this.note = '',
  });

  factory CrewImage.fromJson(Map<String, dynamic> json) {
    String str(String key) => (json[key] ?? '').toString().trim();
    return CrewImage(
      rel: str('rel'),
      name: str('name'),
      source: str('source'),
      note: str('note'),
    );
  }

  final String rel;
  final String name;
  final String source;
  final String note;
}

/// `crew-images.json` loader (optional; the app falls back to the best release
/// screenshot when a crew has no curated image).
class CrewImageIndex {
  CrewImageIndex._(this._byKey, this.loadError, this.generatedAt);

  factory CrewImageIndex.load(String gameinfoDir) {
    if (gameinfoDir.trim().isEmpty) {
      return CrewImageIndex._(const {}, 'GameinfoDirectory not configured', '');
    }
    final file = File('$gameinfoDir/crew-images.json');
    if (!file.existsSync()) {
      return CrewImageIndex._(const {}, null, '');
    }
    try {
      final map = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
      final raw = (map['images'] as Map<String, dynamic>?) ?? const {};
      final byKey = <String, CrewImage>{};
      raw.forEach((key, value) {
        if (value is! Map<String, dynamic>) return;
        final image = CrewImage.fromJson(value);
        if (image.rel.isEmpty || image.name.isEmpty) return;
        byKey[key.trim().toLowerCase()] = image;
      });
      return CrewImageIndex._(
        byKey,
        null,
        (map['generated_at'] ?? '').toString(),
      );
    } catch (e) {
      return CrewImageIndex._(const {}, 'parse error: $e', '');
    }
  }

  static CrewImageIndex empty(String reason) =>
      CrewImageIndex._(const {}, reason, '');

  final Map<String, CrewImage> _byKey;
  final String? loadError;
  final String generatedAt;

  int get length => _byKey.length;

  CrewImage? imageFor(CrewGroup group) =>
      _byKey[group.name.trim().toLowerCase()] ??
      _byKey[group.id.trim().toLowerCase()];
}

/// `crews.json` loader. Missing/unreadable data degrades to an empty index
/// with [loadError] set (the Crews tab then shows a hint instead of failing
/// the whole catalog load).
class CrewIndex {
  CrewIndex._(this.groups, this.loadError, this.generatedAt);

  factory CrewIndex.load(String gameinfoDir) {
    if (gameinfoDir.trim().isEmpty) {
      return CrewIndex._(const [], 'GameinfoDirectory not configured', '');
    }
    final file = File('$gameinfoDir/crews.json');
    if (!file.existsSync()) {
      return CrewIndex._(const [], 'crews.json not found', '');
    }
    try {
      final map = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
      final groups =
          ((map['groups'] as List<dynamic>?) ?? const [])
              .whereType<Map<String, dynamic>>()
              .map(CrewGroup.fromJson)
              .where((g) => g.name.isNotEmpty && !g.excluded)
              .toList()
            ..sort((a, b) {
              final byZips = b.zips.compareTo(a.zips);
              if (byZips != 0) return byZips;
              return a.name.toLowerCase().compareTo(b.name.toLowerCase());
            });
      return CrewIndex._(groups, null, (map['generated_at'] ?? '').toString());
    } catch (e) {
      return CrewIndex._(const [], 'parse error: $e', '');
    }
  }

  static CrewIndex empty(String reason) => CrewIndex._(const [], reason, '');

  final List<CrewGroup> groups;
  final String? loadError;
  final String generatedAt;

  int get length => groups.length;
  int get totalReleases =>
      groups.fold(0, (sum, group) => sum + group.releases.length);

  List<CrewGroup> top(int count) => groups.take(count).toList();
}
